    53  const ADDRESS = /^[A-Z]+[1-9]\d*$/;
    54  const RANGE = /^[A-Z]+[1-9]\d*(?::[A-Z]+[1-9]\d*)?$/;
    55  const isPlainObject = value => value && typeof value === 'object' && !Array.isArray(value) && Object.getPrototypeOf(value) === Object.prototype;
    56
    57  function json(res, status, body) {
    58    const data = JSON.stringify(body);
    59    res.writeHead(status, {'Content-Type':'application/json; charset=utf-8','Content-Length':Buffer.byteLength(data),'Cache-Control':'no-store'});
    60    res.end(data);
    61  }
    62  function fail(res, status, message, extra={}) { json(res, status, {error: message, ...extra}); }
    63  function body(req) {
    64    return new Promise((resolve, reject) => {
    65      let raw = '';
    66      req.on('data', c => { raw += c; if (raw.length > 2_000_000) reject(new Error('Request too large')); });
    67      req.on('end', () => { try { resolve(JSON.parse(raw)); } catch { reject(new Error('Malformed JSON')); } });
    68      req.on('error', reject);
    69    });
    70  }
    71  function getWorkbook(id, revision=null) {
    72    const w = db.prepare('SELECT * FROM workbooks WHERE id=?').get(id);
    73    if (!w) return null;
    74    const r = revision == null ? w.current_revision : revision;
    75    const row = db.prepare('SELECT snapshot,created_at,user_id FROM revisions WHERE workbook_id=? AND revision=?').get(id,r);
    76    return row ? {workbook:JSON.parse(row.snapshot), revision:r, currentRevision:w.current_revision, createdAt:row.created_at, userId:row.user_id} : null;
    77  }
    78  function validWorkbookShape(value, canonical, expectedId) {
    79    if (!isPlainObject(value) || value.id !== expectedId || value.title !== canonical.title || !Array.isArray(value.sheets) || value.sheets.length !== canonical.sheets.length) return false;
    80    return value.sheets.every((sheet, i) => {
    81      const original = canonical.sheets[i];
    82      if (!isPlainObject(sheet) || sheet.id !== original.id || sheet.name !== original.name || !isPlainObject(sheet.cells)) return false;
    83      return Object.entries(sheet.cells).every(([address, cell]) => ADDRESS.test(address) && typeof cell === 'string');
    84    });
    85  }
    86  function sessionRow(id) { return typeof id === 'string' ? db.prepare('SELECT * FROM sessions WHERE id=?').get(id) : null; }
    87  function activePresence(workbookId) {
    88    const cutoff = Date.now() - 15000;
    89    db.prepare('DELETE FROM sessions WHERE last_seen < ?').run(cutoff);
    90    return db.prepare(`SELECT s.id,s.user_id userId,u.name,s.selection,s.color
    91      FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.workbook_id=? ORDER BY s.created_at`).all(workbookId);
    92  }
    93  function broadcast(workbookId, type, payload) {
    94    const message = `event: ${type}\ndata: ${JSON.stringify(payload)}\n\n`;
    95    for (const client of sseClients.values()) if (client.workbookId === workbookId) client.res.write(message);
    96  }
    97  function broadcastPresence(workbookId) { broadcast(workbookId, 'presence', activePresence(workbookId)); }
    98  function requireSession(reqBody, workbookId) {
    99    const session = sessionRow(reqBody.sessionId);
   100    if (!session || session.workbook_id !== workbookId || typeof reqBody.userId !== 'string' || reqBody.userId !== session.user_id) return null;
   101    db.prepare('UPDATE sessions SET last_seen=? WHERE id=?').run(Date.now(), session.id);
   102    return session;
   103  }
