   152    const revMatch = action.match(/^revisions\/(\d+)$/);
   153    if (req.method === 'GET' && revMatch) {
   154      const data=getWorkbook(workbookId,Number(revMatch[1])); return data?json(res,200,data):fail(res,404,'Unknown revision');
   155    }
   156    const histMatch = action.match(/^history\/([^/]+)\/([^/]+)$/);
   157    if (req.method === 'GET' && histMatch) {
   158      const sheetId=decodeURIComponent(histMatch[1]), address=decodeURIComponent(histMatch[2]);
   159      if (!ADDRESS.test(address)) return fail(res,400,'Invalid cell address');
   160      const changes=db.prepare(`SELECT c.revision,c.previous_value previousValue,c.new_value newValue,c.changed_at changedAt,c.user_id userId,u.name
   161        FROM cell_changes c JOIN users u ON u.id=c.user_id WHERE c.workbook_id=? AND c.sheet_id=? AND c.address=? ORDER BY c.id DESC`).all(workbookId,sheetId,address);
   162      const last=changes[0]||null; return json(res,200,{changes,lastChangedBy:last?{userId:last.userId,name:last.name,changedAt:last.changedAt}:null});
