   164    if (req.method === 'POST' && action === 'save') {
   165      const data = await body(req);
   166      const canonical=getWorkbook(workbookId); if (!canonical) return fail(res,404,'Unknown workbook');
   167      if (!isPlainObject(data) || data.workbookId !== workbookId) return fail(res,400,'Workbook id mismatch');
   168      if (!Number.isInteger(data.baseRevision) || data.baseRevision < 1 || data.baseRevision > canonical.currentRevision) return fail(res,400,'Invalid base revision');
   169      const base=getWorkbook(workbookId,data.baseRevision); if (!base) return fail(res,400,'Unknown base revision');
   170      if (!validWorkbookShape(data.workbook,base.workbook,workbookId)) return fail(res,400,'Malformed workbook, sheet, or cells');
   171      const session=requireSession(data,workbookId); if (!session) return fail(res,403,'Unknown editing session or user mismatch');
   172      const edits=[];
   173      for (let i=0;i<base.workbook.sheets.length;i++) {
   174        const oldCells=base.workbook.sheets[i].cells, newCells=data.workbook.sheets[i].cells;
   175        for (const address of new Set([...Object.keys(oldCells),...Object.keys(newCells)])) {
   176          const oldValue=oldCells[address] ?? '', newValue=newCells[address] ?? '';
   177          if (newValue !== oldValue) edits.push({sheetIndex:i,sheetId:base.workbook.sheets[i].id,address,oldValue,newValue});
   178        }
   179      }
   180      const current=getWorkbook(workbookId); const conflicts=[];
   181      for (const e of edits) {
   182        const currentValue=current.workbook.sheets[e.sheetIndex].cells[e.address] ?? '';
   183        if (currentValue !== e.oldValue && currentValue !== e.newValue) conflicts.push({sheetId:e.sheetId,address:e.address,serverValue:currentValue,localValue:e.newValue});
   184      }
   185      if (conflicts.length) return fail(res,409,'Conflicting cell changes',{conflicts,currentRevision:current.currentRevision,workbook:current.workbook});
